// "BE-201 08:00–10:00", or "BE-201 from 08:00" while the end is not decided yet.
import { formatTime } from './time.ts';

export function bookingLabel(lab, start, end) {
  if (end === undefined) return lab + ' from ' + formatTime(start);
  return lab + ' ' + formatTime(start) + '–' + formatTime(end);
}

// Course helper: minutes since 00:00 -> "HH:MM".
export function formatTime(minutes: number): string {
  const h = Math.floor(minutes / 60);
  const m = minutes % 60;
  return String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { bookingLabel } from '../src/label.ts';

test('a closed booking shows both times', () => assert.equal(bookingLabel('BE-201', 480, 600), 'BE-201 08:00–10:00'));
test('an open booking shows only the start', () => assert.equal(bookingLabel('AL-301', 810), 'AL-301 from 13:30'));

import { bookingLabel } from '../src/label.ts';

const closed: string = bookingLabel('BE-201', 480, 600);
const open: string = bookingLabel('BE-201', 480);
console.log(closed, open);

