// How many seats does a booking request ask for? The form may leave the field out or send null.
export function seatsOf({ seats = 1 }: { seats?: number }): number {
  return seats;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { seatsOf } from '../src/seats.ts';

test('no seats key means 1 seat', () => assert.equal(seatsOf({}), 1));
test('seats: null from the form means 1 seat', () => assert.equal(seatsOf({ seats: null }), 1));
test('0 stays 0 (another rule rejects it)', () => assert.equal(seatsOf({ seats: 0 }), 0));
test('12 is 12', () => assert.equal(seatsOf({ seats: 12 }), 12));

import { seatsOf } from '../src/seats.ts';

seatsOf({ seats: '3' }); // expect TS2322
seatsOf({ seat: 3 }); // expect TS2561

