// How many seats does a booking request ask for? The form may leave the field out or send null.
// A default only replaces undefined, so null must be in the type and ?? must handle both.
export function seatsOf(body: { seats?: number | null }): number {
  return body.seats ?? 1;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
