import type { TimeRange } from './types.ts';

// Total booked minutes of a student today.
export function totalMinutes(ranges) {
  let total = 0;
  for (const [start, end] of ranges) total += end - start;
  return total;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { totalMinutes } from '../src/total.ts';

test('no ranges, 0 minutes', () => assert.equal(totalMinutes(), 0));
test('one range', () => assert.equal(totalMinutes([480, 600]), 120));
test('three ranges', () => assert.equal(totalMinutes([480, 600], [600, 720], [780, 840]), 300));

import { totalMinutes } from '../src/total.ts';
import type { TimeRange } from '../src/types.ts';

const today: TimeRange[] = [[480, 600], [780, 840]];
const minutes: number = totalMinutes(...today);
console.log(minutes);

import { totalMinutes } from '../src/total.ts';

totalMinutes([480, 600], 720); // expect TS2345
totalMinutes([480, 600, 660]); // expect TS2345

