// Book a lab. Two flags: e-mail the lecturer? put the booking on a waitlist when the lab is full?
export function book(lab: string, notifyLecturer: boolean, allowWaitlist: boolean): string {
  return lab + (notifyLecturer ? ' · e-mail the lecturer' : '') + (allowWaitlist ? ' · waitlist if full' : '');
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { book } from '../src/book.ts';

test('no options: nothing switched on', () => assert.equal(book('BE-201'), 'BE-201'));
test('only the waitlist', () => assert.equal(book('BE-201', { allowWaitlist: true }), 'BE-201 · waitlist if full'));
test('both', () => assert.equal(book('AL-301', { notifyLecturer: true, allowWaitlist: true }), 'AL-301 · e-mail the lecturer · waitlist if full'));

