// Book a lab. Options are named at every call, both off by default.
export type BookOptions = { notifyLecturer?: boolean; allowWaitlist?: boolean };

export function book(lab: string, { notifyLecturer = false, allowWaitlist = false }: BookOptions = {}): string {
  return lab + (notifyLecturer ? ' · e-mail the lecturer' : '') + (allowWaitlist ? ' · waitlist if full' : '');
}

